namespace sv_f506996b122e47b280d7544d09232f9a.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

/// <summary>
/// Mutable form model for PersonalInfo step.
/// </summary>
public class PersonalInfoModel
{
    public string FullName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string Address { get; set; } = string.Empty;

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

/// <summary>
/// Mutable form model for a single work entry.
/// </summary>
public class WorkEntryModel
{
    public string Company { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public DateTime StartDate { get; set; } = DateTime.Today;
    public DateTime? EndDate { get; set; } = DateTime.Today;
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = string.Empty;

    public WorkEntry ToRecord() => new(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
}

/// <summary>
/// Mutable form model for a single reference.
/// </summary>
public class ReferenceModel
{
    public string Name { get; set; } = string.Empty;
    public string Relationship { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

@namespace sv_f506996b122e47b280d7544d09232f9a.Components.Pages.Application

<nav class="step-indicator" aria-label="Form progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Count; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <li class="step-item @stepClass">
                @if (CompletedSteps.Contains(stepIndex))
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">✓</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(stepIndex == CurrentStep ? "step" : null)">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> Steps { get; set; } = [];
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = new HashSet<int>();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (CompletedSteps.Contains(index)) return "completed";
        return "future";
    }
}

.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0.25rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step-item.active {
    border-bottom-color: #1976d2;
}

.step-item.completed {
    border-bottom-color: #4caf50;
}

.step-item.future {
    opacity: 0.5;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: default;
    font: inherit;
    color: inherit;
    padding: 0;
}

.step-item.completed .step-button {
    cursor: pointer;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    font-weight: bold;
    font-size: 0.875rem;
}

.step-item.active .step-icon {
    background: #1976d2;
    color: white;
}

.step-item.completed .step-icon {
    background: #4caf50;
    color: white;
}

.step-label {
    font-size: 0.8rem;
    white-space: nowrap;
}

